s = Scraper()
soup = s.parse(html)
db = Database("sqlite.db")
currencies = []
i = 0
for row in soup.find_all("tr"):
    a = row.find_all("td")[1].find_all("a")[-1]
    name = a.text
    url = "https://coinmarketcap.com"+a["href"]
    tag = row.find_all("td")[2].text
    print(f"{name} ({tag})")
    c = Coin(tag=tag, name=name, url_coinmarketcap=url, active=i < 50)
    currencies.append(c)
    i+=1

cr = CoinRepository(db)
cr.add_all(currencies)
